"""Assemble ``eval/RESULTS.md`` from saved result files (no recomputation)."""

from __future__ import annotations

import json
from pathlib import Path

from novel_rag.config import Settings


def _read(p: Path) -> str:
    return p.read_text(encoding="utf-8") if p.exists() else ""


def write_report(settings: Settings, novel_ids: list[str]) -> Path:
    parts = ["# Evaluation results", "",
             "_Generated by `novel-rag eval report`. Methodology: see README → Evaluation._", ""]
    for nid in novel_ids:
        info = settings.novel_raw_dir(nid) / "novel.json"
        title = json.loads(info.read_text(encoding="utf-8")).get("title", nid) if info.exists() else nid
        parts += [f"## {title} (`{nid}`)", ""]
        ds = settings.eval_dir / "datasets" / f"{nid}.stats.json"
        if ds.exists():
            d = json.loads(ds.read_text(encoding="utf-8"))
            parts.append(
                f"Dataset: {d['items']} questions — single-hop {d.get('single_hop', 0)}, "
                f"multi-hop {d.get('multi_hop', 0)}, unanswerable {d.get('unanswerable', 0)}.\n"
            )
        kg = settings.kg_dir(nid) / "stats.json"
        if kg.exists():
            k = json.loads(kg.read_text(encoding="utf-8"))
            parts.append(
                f"Knowledge graph: {k['resolved_entities']} entities (from "
                f"{k['raw_entity_mentions']} mentions / {k['distinct_surface_forms']} surface forms), "
                f"{k['relation_edges']} edges from {k['raw_relations_grounded']} grounded relations; "
                f"{k['dropped_relations_ungrounded']} relations and {k['dropped_entities_ungrounded']} "
                f"entities dropped as ungrounded.\n"
            )
        res = settings.eval_dir / "results" / nid
        parts += [_read(res / "retrieval.md"), _read(res / "e2e.md")]
    out = settings.eval_dir / "RESULTS.md"
    out.write_text("\n".join(parts), encoding="utf-8")
    return out
